// ===== EDIT THESE FOR YOUR LAN =====
// Must be reachable FROM THIS NODE-RED HOST (Edge), not only your browser.
// Test on Edge:  curl http://<PMS_IP>:8010/health
// ECONNREFUSED → wrong IP, PMS down, or firewall blocking :8010
//
// Same PC as PMS:  http://127.0.0.1:8010
// PMS LAN PC:      http://192.168.1.216:8010
const PMS_BASE = 'http://192.168.1.216:8010';
const DEVICE_NAME = 'Screw Driver';
const DEVICE_UUID = '7c2fde7c-48b6-475a-98df-bafcc71c6d0d';
const MACHINE_ID = null; // set to number to force match, else null
// ====================================

msg.pmsBase = String(PMS_BASE).replace(/\/$/, '');
msg.deviceName = DEVICE_NAME;
msg.deviceUuid = DEVICE_UUID;
if (MACHINE_ID !== null && MACHINE_ID !== undefined) msg.machineId = MACHINE_ID;
node.status({ fill: 'blue', shape: 'dot', text: msg.pmsBase });
return msg;

// Forward LIVE SIE/EdgeX Screw Driver readings to PMS (no simulation).
const src = msg.payload || {};
const incoming = Array.isArray(src.readings) ? src.readings : [];
if (!incoming.length) {
    node.status({ fill: 'yellow', shape: 'ring', text: 'no readings' });
    return null;
}

function stripType(name) {
    let s = String(name || '').trim();
    for (const sep of [';', ':']) {
        if (s.indexOf(sep) >= 0) {
            s = s.split(sep, 1)[0].trim();
            break;
        }
    }
    return s;
}

const origin = Number(src.origin) || Date.now();
const byName = {};
let torque = null;
let position = null;
let result = null;
let runningStatus = null;

for (const r of incoming) {
    if (!r || r.name == null) continue;
    const name = String(r.name);
    let value = r.value;
    if (value === undefined || value === null) value = '';
    value = String(value);
    byName[name] = {
        name: name,
        value: value,
        origin: Number(r.origin) || origin
    };
    const base = stripType(name).toLowerCase().replace(/[\s_]+/g, '');
    if (base === 'torquevalue' || base === 'torque') torque = value;
    if (base === 'positionvalue' || base === 'position') position = value;
    if (base === 'result') result = value;
    if (base === 'runningstatus' || base === 'runstatus') runningStatus = value;
}

if (!byName['device_type;String'] && !byName['device_type'] && !byName['device type;String']) {
    byName['device_type;String'] = {
        name: 'device_type;String',
        value: 'ScrewDriver',
        origin: origin
    };
}

const readings = Object.keys(byName).map(k => byName[k]);

const body = {
    id: src.id || ('screw-' + origin),
    syncBy: src.syncBy || 'MODBUS',
    deviceName: msg.deviceName || src.deviceName || 'Screw_Driver',
    device: msg.deviceUuid || src.device,
    origin: origin,
    readings: readings,
    replaceReadings: true
};
if (msg.machineId) body.machine_id = msg.machineId;

msg.payload = body;
msg.headers = { 'Content-Type': 'application/json' };
msg.url = msg.pmsBase + '/api/machines/telemetry';
msg.method = 'POST';

node.status({
    fill: 'green',
    shape: 'dot',
    text: 'T=' + (torque != null ? torque : '?') +
        ' P=' + (position != null ? position : '?') +
        ' R=' + (result != null ? result : '?') +
        ' S=' + (runningStatus != null ? runningStatus : '?') + ' -> PMS'
});
return msg;

const code = msg.statusCode || 0;
const body = msg.payload;
const url = msg.url || '';
const errStr = String((msg.error && (msg.error.message || msg.error)) || body || '');
const refused = /ECONNREFUSED/i.test(errStr) || /ECONNREFUSED/i.test(JSON.stringify(body || {}));

if (code >= 200 && code < 300 && body && typeof body === 'object') {
    const scaled = body.scaled || {};
    node.status({
        fill: 'green',
        shape: 'dot',
        text: 'ok T=' + (scaled.torque != null ? scaled.torque : '-') +
            ' P=' + (scaled.position_value != null ? scaled.position_value : '-')
    });
} else if (refused) {
    node.status({
        fill: 'red',
        shape: 'ring',
        text: ('ECONNREFUSED ' + url).slice(0, 60)
    });
} else {
    const detail = (body && body.detail) ? String(body.detail).slice(0, 36) : errStr.slice(0, 36);
    node.status({ fill: 'red', shape: 'ring', text: ('fail ' + code + ' ' + detail).slice(0, 60) });
}
return msg;

// Same PMS_BASE as cfg node — keep in sync
const PMS_BASE = 'http://192.168.1.216:8010';
msg.method = 'GET';
msg.url = String(PMS_BASE).replace(/\/$/, '') + '/health';
msg.headers = {};
msg.payload = {};
node.status({ fill: 'blue', shape: 'ring', text: msg.url });
return msg;

const code = msg.statusCode || 0;
const body = msg.payload;
const errStr = String((msg.error && (msg.error.message || msg.error)) || '');
if (code >= 200 && code < 300) {
    node.status({ fill: 'green', shape: 'dot', text: 'PMS reachable ' + code });
} else if (/ECONNREFUSED/i.test(errStr) || /ECONNREFUSED/i.test(String(body))) {
    node.status({ fill: 'red', shape: 'ring', text: 'ECONNREFUSED — Edge cannot reach PMS_BASE' });
} else {
    node.status({ fill: 'red', shape: 'ring', text: ('fail ' + code + ' ' + errStr).slice(0, 50) });
}
return msg;
